#!/usr/bin/env python3
"""
branding/build.py — generates every derived raster asset from the SVG masters
in branding/ (wordmark-dark.svg, wordmark-light.svg, mark.svg) into
site/assets/. Nothing in site/assets/ should be hand-exported; if you need a
new derived asset, add it here.

Outputs (all written under site/assets/):
  favicon.svg            square goal-light icon, dark rounded background
  favicon-16.png          16x16
  favicon-32.png          32x32
  favicon.ico             multi-size (16/32/48) ICO built from the above
  apple-touch-icon.png    180x180
  og-image.png            1280x640 OG/social card, dark ground, wordmark +
                          positioning line

Requires:
  - rsvg-convert (librsvg) on PATH — rasterizes the SVG masters.
    macOS: brew install librsvg
  - Pillow (PIL) — composites the favicon square and builds the ICO/OG card.
    pip install pillow

Idempotent: re-running always regenerates every output from the masters, so
there is nothing to clean up first. Run as:

  python3 branding/build.py
"""
import shutil
import subprocess
import sys
from pathlib import Path

try:
    from PIL import Image, ImageDraw, ImageFont
except ImportError:
    sys.exit(
        "branding/build.py requires Pillow. Install it with: pip install pillow"
    )

ROOT = Path(__file__).resolve().parent.parent
BRANDING = ROOT / "branding"
ASSETS = ROOT / "site" / "assets"

MARK_SVG = BRANDING / "mark.svg"
WORDMARK_DARK_SVG = BRANDING / "wordmark-dark.svg"

# Dark palette (branding/BRAND.md) — the favicon and OG card are fixed dark
# artifacts regardless of the viewer's color scheme, same as the mark itself.
BG = (7, 11, 20)          # #070b14
TEXT = (232, 238, 247)    # #e8eef7
MUTED = (147, 164, 189)   # #93a4bd
ACCENT_HOT = (255, 106, 61)   # #ff6a3d
ACCENT = (255, 59, 47)        # #ff3b2f

