def check_deps():
    if shutil.which("rsvg-convert") is None:
        sys.exit(
            "branding/build.py requires rsvg-convert (librsvg) on PATH.\n"
            "macOS: brew install librsvg"
        )


def rsvg_render(svg_path: Path, out_path: Path, width: int, height: int | None = None):
    cmd = ["rsvg-convert", "-w", str(width)]
    if height is not None:
        cmd += ["-h", str(height)]
    cmd += ["--keep-aspect-ratio", str(svg_path), "-o", str(out_path)]
    subprocess.run(cmd, check=True)


def render_svg_text(svg_text: str, out_path: Path, width: int, height: int):
    tmp = out_path.with_suffix(".src.svg")
    tmp.write_text(svg_text)
    try:
        subprocess.run(
            ["rsvg-convert", "-w", str(width), "-h", str(height), str(tmp), "-o", str(out_path)],
            check=True,
        )
    finally:
        tmp.unlink(missing_ok=True)


def build_favicon_square():
    """Write the square favicon.svg (dark rounded bg + mark) and rasterize it
    at the sizes browsers actually request."""
    fav_svg = ASSETS / "favicon.svg"
    fav_svg.write_text(FAVICON_SQUARE_SVG)

    sizes = {"favicon-16.png": 16, "favicon-32.png": 32}
    for name, size in sizes.items():
        render_svg_text(FAVICON_SQUARE_SVG, ASSETS / name, size, size)

    # a 48px render feeds the ICO too (Windows favicon convention)
    tmp48 = ASSETS / "_favicon-48.tmp.png"
    render_svg_text(FAVICON_SQUARE_SVG, tmp48, 48, 48)

    icon_16 = Image.open(ASSETS / "favicon-16.png")
    icon_32 = Image.open(ASSETS / "favicon-32.png")
    icon_48 = Image.open(tmp48)
    icon_32.save(
        ASSETS / "favicon.ico",
        sizes=[(16, 16), (32, 32), (48, 48)],
        append_images=[icon_16, icon_48],
    )
    tmp48.unlink(missing_ok=True)

    # apple-touch-icon: same square art at 180x180, no transparency expected
    # by iOS, so flatten onto the dark background it already contains.
    render_svg_text(FAVICON_SQUARE_SVG, ASSETS / "apple-touch-icon.png", 180, 180)


def load_font(candidates, size):
    for path in candidates:
        p = Path(path)
        if p.exists():
            return ImageFont.truetype(str(p), size)
    return ImageFont.load_default()


# System sans/mono fallbacks used only for the OG card's raster text layer —
# the site itself never depends on these; it uses the Google Fonts stack.
SANS_CANDIDATES = [
    "/System/Library/Fonts/Supplemental/Arial.ttf",
    "/System/Library/Fonts/Helvetica.ttc",
    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
]
MONO_CANDIDATES = [
    "/System/Library/Fonts/Supplemental/Andale Mono.ttf",
    "/System/Library/Fonts/Menlo.ttc",
    "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf",
]


def build_og_card():
    """1280x640 OG/social card: dark ground, wordmark, positioning line."""
    W, H = 1280, 640
    card = Image.new("RGB", (W, H), BG)
    draw = ImageDraw.Draw(card)

    # subtle top-down vignette so the flat dark ground doesn't look inert
    for y in range(H):
        t = y / H
        shade = tuple(int(BG[c] + (10 * (1 - t))) for c in range(3))
        draw.line([(0, y), (W, y)], fill=shade)

    # wordmark, rendered from the dark master, placed left-aligned
    wm_w = 760
    wm_h = int(wm_w * 345 / 1350)
    wm_png = ASSETS / "_og-wordmark.tmp.png"
    rsvg_render(WORDMARK_DARK_SVG, wm_png, wm_w, wm_h)
    wordmark = Image.open(wm_png).convert("RGBA")
    wm_x = (W - wm_w) // 2
    wm_y = 150
    card.paste(wordmark, (wm_x, wm_y), wordmark)
    wm_png.unlink(missing_ok=True)

    # positioning line, centered under the wordmark
    sans = load_font(SANS_CANDIDATES, 40)
    mono = load_font(MONO_CANDIDATES, 24)

    line = "Your team scores. Your house reacts."
    bbox = draw.textbbox((0, 0), line, font=sans)
    tw = bbox[2] - bbox[0]
    draw.text(((W - tw) // 2, wm_y + wm_h + 46), line, font=sans, fill=TEXT)

    meta = "goalfeed.ca  ·  self-hosted  ·  open source"
    bbox2 = draw.textbbox((0, 0), meta, font=mono)
    mw = bbox2[2] - bbox2[0]
    draw.text(((W - mw) // 2, H - 74), meta, font=mono, fill=MUTED)

    card.save(ASSETS / "og-image.png", "PNG")


def copy_wordmark_svgs():
    """The site (site/assets/) is the only directory GitHub Pages publishes
    (.github/workflows/pages.yml ships ./site only) — branding/ is not
    servable, so the wordmark masters are copied verbatim into site/assets/
    for the site and README to reference. branding/*.svg stays canonical;
    these are plain copies, never hand-edited."""
    for name in ("wordmark-dark.svg", "wordmark-light.svg", "mark.svg"):
        shutil.copyfile(BRANDING / name, ASSETS / name)


def main():
    check_deps()
    ASSETS.mkdir(parents=True, exist_ok=True)
    copy_wordmark_svgs()
    build_favicon_square()
    build_og_card()
    print("Wrote wordmark-dark.svg, wordmark-light.svg, mark.svg (copied),")
    print("favicon.svg, favicon-16.png, favicon-32.png, favicon.ico,")
    print(f"apple-touch-icon.png, og-image.png -> {ASSETS}")


if __name__ == "__main__":
    main()
